package com.tekwatt.firmware.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="firmware_packages",uniqueConstraints=@UniqueConstraint(name="uk_firmware_vendor_model_version",columnNames={"vendor","model","version"}))public class FirmwarePackage{@Id private UUID id;@Column(nullable=false,length=100)private String vendor;@Column(nullable=false,length=100)private String model;@Column(nullable=false,length=60)private String version;@Column(nullable=false,length=1000)private String downloadUrl;@Column(nullable=false,length=128)private String checksum;@Column(nullable=false,length=20)private String checksumAlgorithm;@Column(length=2000)private String signature;@Column(nullable=false)private Long fileSizeBytes;@Column(nullable=false)private Boolean active;@Column(nullable=false,updatable=false)private Instant createdAt;protected FirmwarePackage(){}public FirmwarePackage(String vendor,String model,String version,String url,String checksum,String algorithm,String signature,Long size){id=UUID.randomUUID();this.vendor=vendor;this.model=model;this.version=version;downloadUrl=url;this.checksum=checksum;checksumAlgorithm=algorithm;this.signature=signature;fileSizeBytes=size;active=true;createdAt=Instant.now();}public UUID getId(){return id;}public String getVendor(){return vendor;}public String getModel(){return model;}public String getVersion(){return version;}public String getDownloadUrl(){return downloadUrl;}public String getChecksum(){return checksum;}public String getChecksumAlgorithm(){return checksumAlgorithm;}public String getSignature(){return signature;}public Long getFileSizeBytes(){return fileSizeBytes;}public Boolean getActive(){return active;}public Instant getCreatedAt(){return createdAt;}}
